import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { ToastController, LoadingController, AlertController } from '@ionic/angular';
import { GResponse } from 'src/app/core/common/GResponse';
import { SharedIonic } from 'src/app/core/common/SharedIonic';
import { ICourseFilterModel, CourseFilterModel } from 'src/app/data/model/course/CourseFilterModel';
import { CourseService } from 'src/app/data/service/course/course.service';
import { ICourseDetailModel } from '../../../../../data/model/course/CourseDetailModel';
import { ICourseModel } from '../../../../../data/model/course/CourseModel';
import { G } from '../../../../../core/common/G';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { TeacherPortionModel } from '../../../../../data/model/course/CourseVideoModel';
import { DomSanitizer } from '@angular/platform-browser';

@Component({
  selector: 'app-course-state',
  templateUrl: './course-state.component.html',
  styleUrls: ['./course-state.component.scss']
})
export class CourseStateComponent implements OnInit {

  selectedCourseId = 0;
  selectedCategory = '2';
  teacherPercent = -1;
  selected = false;
  teacherPercentEdit = false;
  filteredCourses: ICourseFilterModel;
  selectedCourse: ICourseDetailModel;
  courseCategores = [];
  updateForm: FormGroup;
  searchTitle = '';
  isEdited = false;

  constructor(
    private courseService: CourseService,
    public toastController: ToastController,
    private fb: FormBuilder,
    public loadingController: LoadingController,
    private activatedRoute: ActivatedRoute,
    private router: Router,
    public alertController: AlertController,
    private sanitizer: DomSanitizer
  ) { }

  onCategoryClick(catName: string) {

    G.getCourseCategory().subscribe(
      res => {
        res.forEach(cat => {
          if (cat.title === catName) {
            this.router
              .navigate(
                ['Home', 'Search'],
                {
                  queryParams:
                  {
                    categoryIds: [cat.courseCategoryId]
                  }
                });
            return;
          }
        });
      }
    );
  }

  checkURL() {
    let url = 'https://www.aparat.com/video/video/embed/videohash/' +
      this.selectedCourse.videoUrl +
      '/vt/frame';

    return this.sanitizer.bypassSecurityTrustResourceUrl(url);
  }

  checkVideoUrl() {
    let url = 'https://www.aparat.com/v/' +
      this.selectedCourse.videoUrl;

    return this.sanitizer.bypassSecurityTrustResourceUrl(url);
  }

  ngOnInit(): void {

    this.updateForm = this.fb.group({
      percent: ['', [Validators.required, Validators.min(0), Validators.max(100)]]
    });

    let filter: ICourseFilterModel;

    this.activatedRoute.queryParams.subscribe(params => {

      const page = params.page;
      const take = params.take ? params.take : 12;
      const title = params.title ? params.title : null;
      const startPrice = params.startPrice ? params.startPrice : null;
      const endPrice = params.endPrice ? params.endPrice : null;
      const categoryIds = params.categoryIds ? params.categoryIds : [];
      const sortId = params.sortId ? params.sortId : 4;

      if (page === undefined) {
        filter = new CourseFilterModel(true, page, take, title, startPrice, endPrice, categoryIds, sortId);
      } else {


        if (
          startPrice == null &&
          endPrice == null &&
          categoryIds == null &&
          sortId == null) {

          filter = new CourseFilterModel(false, page, take, title);
        } else {
          filter =
            new CourseFilterModel(true, page, take, title, startPrice, endPrice, categoryIds, sortId);
        }
      }
      this.filteredCourses = filter;

      this.getDate(this.selectedCategory);
    });
  }

  percentEditEnabled() {

    this.updateForm.setValue({ percent: this.teacherPercent });
    this.teacherPercentEdit = true;
  }

  percentEdit() {

    if (!this.updateForm.valid) {
      return;
    }

    SharedIonic.loading(this.loadingController);

    this.courseService.AddOrUpdateTeacherPortion(
      new TeacherPortionModel(this.selectedCourseId, +this.updateForm.value.percent)
    )
      .subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (res.status === GResponse.SuccessStatus) {
            this.teacherPercent = +this.updateForm.value.percent;
            this.updateForm.setValue({ percent: '' });
            this.teacherPercentEdit = false;
            SharedIonic.successToast(this.toastController);
          } else {
            SharedIonic.unSuccessToast(this.toastController);
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
  }

  categoryChanged() {

    this.getDate(this.selectedCategory);
  }

  getDate(type: string) {

    SharedIonic.loading(this.loadingController);

    switch (type) {
      case '1':
        this.courseService.GetCoursesByFilter(this.filteredCourses).subscribe(
          res => {
            SharedIonic.dismissLoading(this.loadingController);
            if (res.status === GResponse.SuccessStatus) {
              this.filteredCourses = res.data;
            } else if (res.status === GResponse.NotFoundStatus) {
              this.filteredCourses.courses = [];
            } else {
              SharedIonic.unSuccessToast(this.toastController);
              this.filteredCourses.courses = [];
            }
          },
          err => {
            this.filteredCourses.courses = [];
            SharedIonic.dismissLoading(this.loadingController);
            SharedIonic.unSuccessToast(this.toastController);
          }
        );
        break;
      case '2':
        this.courseService.GetDeActiveCoursesByFilter(this.filteredCourses).subscribe(
          res => {
            SharedIonic.dismissLoading(this.loadingController);
            if (res.status === GResponse.SuccessStatus) {
              this.filteredCourses = res.data;
            } else if (res.status === GResponse.NotFoundStatus) {
              this.filteredCourses.courses = [];
            } else {
              this.filteredCourses.courses = [];
              SharedIonic.unSuccessToast(this.toastController);
            }
          },
          err => {
            this.filteredCourses.courses = [];
            SharedIonic.dismissLoading(this.loadingController);
            SharedIonic.unSuccessToast(this.toastController);
          }
        );
        break;
      case '3':
        this.courseService.GetEditCoursesByFilter(this.filteredCourses).subscribe(
          res => {
            SharedIonic.dismissLoading(this.loadingController);
            if (res.status === GResponse.SuccessStatus) {
              this.filteredCourses = res.data;
            } else if (res.status === GResponse.NotFoundStatus) {
              this.filteredCourses.courses = [];
            } else {
              this.filteredCourses.courses = [];
              SharedIonic.unSuccessToast(this.toastController);
            }
          },
          err => {
            this.filteredCourses.courses = [];
            SharedIonic.dismissLoading(this.loadingController);
            SharedIonic.unSuccessToast(this.toastController);
          }
        );
        break;
      default:
        this.courseService.GetCoursesByFilter(this.filteredCourses).subscribe(
          res => {
            SharedIonic.dismissLoading(this.loadingController);
            if (res.status === GResponse.SuccessStatus) {
              this.filteredCourses = res.data;
            } else if (res.status === GResponse.NotFoundStatus) {
              this.filteredCourses.courses = [];
            } else {
              SharedIonic.unSuccessToast(this.toastController);
              this.filteredCourses.courses = [];
            }
          },
          err => {
            this.filteredCourses.courses = [];
            SharedIonic.dismissLoading(this.loadingController);
            SharedIonic.unSuccessToast(this.toastController);
          }
        );
        break;
    }
  }

  // eslint-disable-next-line @typescript-eslint/naming-convention
  MakePageCountArray(pageCount: number | string): Array<number | string> {

    const array: string[] = [];

    for (let i = 1; i <= pageCount; i++) {

      array.push(i.toString());
    }

    return array;
  }

  goPreviousPage() {

    if (this.filteredCourses.startPage == null) {
      return;
    }
    if (this.filteredCourses.pageId > this.filteredCourses.startPage && +this.filteredCourses.pageId - 1 > 0) {
      this.setQueryParams(+this.filteredCourses.pageId - 1);
    }
  }

  goNextPage() {

    if (this.filteredCourses.endPage == null) {
      return;
    }
    if (this.filteredCourses.pageId < this.filteredCourses.endPage) {
      this.setQueryParams(+this.filteredCourses.pageId + 1);
    }
  }

  goPage(pageId: number | string) {
    this.setQueryParams(+pageId);
  }

  public setQueryParams(pageId: number) {

    this.filteredCourses.title = this.searchTitle;

    this.router
      .navigate(
        ['AdminPanel', 'CourseState'],
        {
          queryParams:
          {
            page: pageId < 1 ? 1 : pageId,
            take: this.filteredCourses.takeEntity ? this.filteredCourses.takeEntity : null,
            title: this.filteredCourses.title ? this.filteredCourses.title : null,
            startPrice: this.filteredCourses.startPrice ? this.filteredCourses.startPrice : null,
            endPrice: this.filteredCourses.endPrice ? this.filteredCourses.endPrice : null,
            categoryIds: this.filteredCourses.categoryIds ? this.filteredCourses.categoryIds : [],
            sortId: this.filteredCourses.sortId ? this.filteredCourses.sortId : 4
          }
        });
  }

  onActiveEdit(): void {

    SharedIonic.loading(this.loadingController);

    this.courseService.ActiveEditCourseById(+this.selectedCourseId).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (GResponse.SuccessStatus === res.status) {
          SharedIonic.successToast(this.toastController);
          this.selected = false;
          this.getDate(this.selectedCategory);
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  onActive(): void {

    SharedIonic.loading(this.loadingController);

    this.courseService.ActiveCourseById(+this.selectedCourseId).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (GResponse.SuccessStatus === res.status) {
          SharedIonic.successToast(this.toastController);
          this.selected = false;
          this.getDate(this.selectedCategory);
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  onActiveNoShare(): void {

    SharedIonic.loading(this.loadingController);

    this.courseService.ActiveCourseByIdNoShare(+this.selectedCourseId).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (GResponse.SuccessStatus === res.status) {
          SharedIonic.successToast(this.toastController);
          this.selected = false;
          this.getDate(this.selectedCategory);
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  onDeActive(): void {

    SharedIonic.loading(this.loadingController);

    this.courseService.DeActiveCourseById(+this.selectedCourseId).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (GResponse.SuccessStatus === res.status) {
          SharedIonic.successToast(this.toastController);
          this.selected = false;
          this.getDate(this.selectedCategory);
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  async presentActiveAlertConfirm() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به فعال کردن هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onActive();
          }
        }
      ]
    });

    await alert.present();
  }

  async presentActiveEditAlertConfirm() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onActiveEdit();
          }
        }
      ]
    });

    await alert.present();
  }

  async presentActiveAlertConfirmNoShare() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به فعال کردن هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onActiveNoShare();
          }
        }
      ]
    });

    await alert.present();
  }

  async presentDeActiveAlertConfirm() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به غیر فعال کردن هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onDeActive();
          }
        }
      ]
    });

    await alert.present();
  }

  getTeacherName() {

    if (this.selectedCourse.teacherUser === undefined || this.selectedCourse.teacherUser == null) {

      return '';
    }
    const name = this.selectedCourse.teacherUser.name != null ? this.selectedCourse.teacherUser.name : '';
    const family = this.selectedCourse.teacherUser.family != null ? this.selectedCourse.teacherUser.family : '';

    return name + ' ' + family;
  }

  onSelectItem(model: ICourseModel) {

    this.selectedCourseId = +model.id;
    this.isEdited = this.filteredCourses.courses.find(e => e.id === +model.id).isEdited;

    SharedIonic.loading(this.loadingController);

    this.courseService.GetTeacherPortion(+model.id).subscribe(
      res => {
        if (GResponse.SuccessStatus === res.status) {

          this.teacherPercent = res.data;
        } else {
          SharedIonic.unSuccessToast(this.toastController);
          this.teacherPercent = -1;
        }
      },
      err => {
        SharedIonic.unSuccessToast(this.toastController);
        this.teacherPercent = -1;
      }
    );

    if (this.selectedCategory === '1') {

      this.courseService.GetCourseById(+this.selectedCourseId).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (GResponse.SuccessStatus === res.status) {
            this.selectedCourse = res.data;
            this.selectedCourse.imageUrl = this.filteredCourses.courses.find(e => e.id === +model.id).imageUrl;
            this.selected = true;

            G.getCourseCategory().subscribe(
              res2 => {

                this.courseCategores = [];

                res2.forEach(cat => {

                  this.selectedCourse.categoryIds.forEach(ccat => {

                    if (+ccat === +cat.courseCategoryId) {

                      this.courseCategores.push(cat.title);
                    }
                  });
                });
              }
            );
          } else {
            SharedIonic.unSuccessToast(this.toastController);
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    }
    else if(this.selectedCategory === '2') {

      this.courseService.GetDeActiveCourseById(+this.selectedCourseId).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (GResponse.SuccessStatus === res.status) {
            this.selectedCourse = res.data;
            this.selectedCourse.imageUrl = this.filteredCourses.courses.find(e => e.id === +model.id).imageUrl;
            this.selected = true;

            G.getCourseCategory().subscribe(
              res2 => {

                this.courseCategores = [];

                res2.forEach(cat => {

                  this.selectedCourse.categoryIds.forEach(ccat => {

                    if (+ccat === +cat.courseCategoryId) {

                      this.courseCategores.push(cat.title);
                    }
                  });
                });
              }
            );
          } else {
            SharedIonic.unSuccessToast(this.toastController);
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );

    }else {

      this.courseService.GetCourseEditById(+this.selectedCourseId).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (GResponse.SuccessStatus === res.status) {
            this.selectedCourse = res.data;
            this.selectedCourse.imageUrl = this.filteredCourses.courses.find(e => e.id === +model.id).imageUrl;
            this.selected = true;

            G.getCourseCategory().subscribe(
              res2 => {

                this.courseCategores = [];

                res2.forEach(cat => {

                  this.selectedCourse.categoryIds.forEach(ccat => {

                    if (+ccat === +cat.courseCategoryId) {

                      this.courseCategores.push(cat.title);
                    }
                  });
                });
              }
            );
          } else {
            SharedIonic.unSuccessToast(this.toastController);
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );

    }
  }
}
